package org.pocketsurf.browser
import android.app.DownloadManager
import android.content.Intent
import android.graphics.*
import android.graphics.drawable.GradientDrawable
import android.net.Uri
import android.view.*
import android.webkit.WebView
import android.widget.*
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.*
import org.robolectric.annotation.Config
import org.robolectric.annotation.GraphicsMode
import java.time.Duration

@RunWith(RobolectricTestRunner::class)
@Config(sdk=[33],qualifiers="w960dp-h540dp-land-mdpi",shadows=[RecordingWebViewShadow::class])
@GraphicsMode(GraphicsMode.Mode.NATIVE)
class Surf129RegressionTest{
 private val app get()=RuntimeEnvironment.getApplication()
 @Before fun reset(){app.getSharedPreferences("browser",0).edit().clear().putBoolean(SetupActivity.COMPLETE,true).commit();app.getSharedPreferences("downloads",0).edit().clear().commit();RecordingWebViewShadow.clearEvidence()}
 private fun field(a:BrowserActivity,n:String)=BrowserActivity::class.java.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun put(a:BrowserActivity,n:String,v:Any?)=BrowserActivity::class.java.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun call(a:BrowserActivity,n:String,vararg args:Any?)=BrowserActivity::class.java.declaredMethods.first{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun all(v:View):List<View> = listOf(v)+if(v is ViewGroup)(0 until v.childCount).flatMap{all(v.getChildAt(it))}else emptyList()
 private fun settle(a:BrowserActivity,millis:Long=100){repeat(3){val d=a.resources.displayMetrics;a.window.decorView.apply{measure(View.MeasureSpec.makeMeasureSpec(d.widthPixels,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(d.heightPixels,View.MeasureSpec.EXACTLY));layout(0,0,measuredWidth,measuredHeight)};TestFrameClock.advance(Duration.ofMillis(millis))}}
 private fun start()=Robolectric.buildActivity(BrowserActivity::class.java,Intent(Intent.ACTION_VIEW,Uri.parse("https://fixture.test/"))).setup().visible().also{settle(it.get())}
 private fun key(a:BrowserActivity,k:Int){a.dispatchKeyEvent(KeyEvent(0,k));a.dispatchKeyEvent(KeyEvent(1,k));settle(a)}
 private fun desc(a:BrowserActivity,n:String)=all(a.window.decorView).first{it.contentDescription==n&&it.isShown}
 private fun stick(a:BrowserActivity,x:Float,y:Float){val props=MotionEvent.PointerProperties().apply{id=0};val axes=MotionEvent.PointerCoords().apply{setAxisValue(MotionEvent.AXIS_X,x);setAxisValue(MotionEvent.AXIS_Y,y)};val e=MotionEvent.obtain(0,0,MotionEvent.ACTION_MOVE,1,arrayOf(props),arrayOf(axes),0,0,1f,1f,0,0,InputDevice.SOURCE_JOYSTICK,0);a.dispatchGenericMotionEvent(e);e.recycle();settle(a)}
 private fun shot(a:BrowserActivity,n:String){val v=a.window.decorView;val b=Bitmap.createBitmap(v.width,v.height,Bitmap.Config.ARGB_8888);v.draw(Canvas(b));java.io.File("build/reports/surf129/$n.png").apply{parentFile.mkdirs();outputStream().use{b.compress(Bitmap.CompressFormat.PNG,100,it)}};b.recycle()}
 @Test fun mouseStickNavigatesSurfBarAndVerticalInputCannotEscape(){val c=start();val a=c.get();key(a,106);put(a,"pointerX",123f);key(a,100);assertEquals("New tab",(field(a,"focused") as View).contentDescription);key(a,20);key(a,19);assertEquals(true,field(a,"surfBarActive"));assertEquals("New tab",(field(a,"focused") as View).contentDescription);stick(a,1f,0f);assertEquals("Open tabs",(field(a,"focused") as View).contentDescription);stick(a,0f,0f);stick(a,0f,1f);assertEquals(true,field(a,"surfBarActive"));assertEquals("Open tabs",(field(a,"focused") as View).contentDescription);key(a,97);assertEquals(false,field(a,"surfBarActive"));assertEquals(123f,field(a,"pointerX") as Float,.01f);c.pause().stop().destroy()}
 @Test fun staleKeyboardFlagsCannotPermanentlyDisableController(){val c=start();val a=c.get();put(a,"webEditing",true);put(a,"imeExpected",true);put(a,"editRequestedAt",android.os.SystemClock.uptimeMillis()-2000);put(a,"nativeTyping",true);key(a,100);assertEquals(false,field(a,"webEditing"));assertEquals(false,field(a,"nativeTyping"));assertEquals(true,field(a,"surfBarActive"));c.pause().stop().destroy()}
 @Test fun chromeHasCenteredSubtleTriggersAndNoYBadgeOrSelectionBackground(){val c=start();val a=c.get();val bar=field(a,"surfBar") as ViewGroup;assertTrue(all(bar).none{it.contentDescription?.startsWith("Surf Bar shortcut:")==true});val trigger=desc(a,"Previous tab shortcut") as ViewGroup;assertEquals(26,trigger.width);val label=all(trigger).filterIsInstance<TextView>().first();val lp=label.layoutParams as FrameLayout.LayoutParams;assertEquals(Gravity.CENTER,lp.gravity);key(a,100);key(a,22);val v=field(a,"focused") as View;assertNull(v.foreground);assertTrue(v.background==null||(v.background as? GradientDrawable)?.color?.defaultColor==Color.TRANSPARENT);shot(a,"surf-bar");c.pause().stop().destroy()}
 @Test fun zoomSliderReflowsLayoutAndResetRestores100WithoutScrolling(){val c=start();val a=c.get();key(a,107);val layer=field(a,"popupLayer") as View;assertTrue(all(layer).none{it is ScrollView});val slider=desc(a,"Page zoom slider") as SeekBar;key(a,22);assertEquals(55,slider.progress);assertTrue(RecordingWebViewShadow.scripts.any{it.contains("setZoom(105,")});desc(a,"Reset · 100%").performClick();assertEquals(50,slider.progress);assertEquals(100,(call(a,"getTab") as BrowserActivity.Tab).zoomPercent);shot(a,"zoom-slider");c.pause().stop().destroy()}
 @Test @Config(qualifiers="w640dp-h360dp-land-mdpi") fun sizeSliderAndPermanentPreviewFitMousePage(){val c=start();val a=c.get();call(a,"showMouseSettings");settle(a);val slider=desc(a,"Pointer size") as SeekBar;slider.progress=150;val cursor=field(a,"mousePreviewCursor") as MousePointer;assertEquals(View.VISIBLE,cursor.visibility);assertEquals(20,cursor.layoutParams.width);val scroll=field(a,"nativeScroll") as ScrollView;assertFalse(scroll.canScrollVertically(1));shot(a,"mouse-size");c.pause().stop().destroy()}
 @Test fun appearanceKeepsChosenFocusAndSeparatesShapeFillOutline(){val c=start();val a=c.get();call(a,"showMouseSettings");desc(a,"Mouse Appearance").performClick();settle(a);val layer=field(a,"popupLayer") as View;assertTrue(all(layer).none{it.contentDescription=="Pointer size"});assertEquals(5,all(layer).count{it.contentDescription?.startsWith("Pointer style:")==true});val rock=desc(a,"Pointer style: Rock hand");rock.requestFocus();rock.performClick();assertSame(rock,field(a,"focused"));desc(a,"Fill: Accent").performClick();desc(a,"Outline: White").performClick();val prefs=a.getSharedPreferences("browser",0);val clean=BackupCodec.validate(BackupCodec.export(prefs));assertEquals("rock",clean.getString("pointer_style"));assertEquals("accent",clean.getString("pointer_fill"));assertEquals("white",clean.getString("pointer_outline"));assertTrue(all(layer).filterIsInstance<MousePointer>().all{it.background==null});shot(a,"mouse-appearance");c.pause().stop().destroy()}
 @Test fun downloadStateAggregatesProgressAndNeverMarksCancellationSuccessful(){fun item(id:Long,status:Int,received:Long=0,total:Long=0)=SurfDownload(id,"https://fixture.test/","file.bin","application/octet-stream",0,status,received,total)
  val a=item(1,DownloadManager.STATUS_RUNNING,25,100);val b=item(2,DownloadManager.STATUS_RUNNING,75,100);val running=DownloadIndicator.from(listOf(a,b),emptySet());assertEquals(2,running.active);assertEquals(.5f,running.fraction!!,.001f);assertNull(DownloadIndicator.from(listOf(a,b.copy(total=0)),emptySet()).fraction);assertFalse(DownloadIndicator.from(listOf(item(3,SurfDownloads.CANCELLED)),emptySet()).completed);assertTrue(DownloadIndicator.from(listOf(item(4,DownloadManager.STATUS_SUCCESSFUL)),emptySet()).completed);assertFalse(DownloadIndicator.from(listOf(item(4,DownloadManager.STATUS_SUCCESSFUL)),setOf("4")).completed);assertNotEquals(DownloadIndicator.color(Color.BLUE),DownloadIndicator.color(Color.RED))}
 @Test fun downloadIconTracksGeneratedTransferAndClearsCompletionOnOpen(){val c=start();val a=c.get();val downloads=call(a,"getDownloads") as SurfDownloads;val item=downloads.generated("blob:https://fixture.test/id","sample.bin","application/octet-stream",Uri.parse("content://fixture/file"));call(a,"refreshDownloadIndicator",false);val image=(desc(a,"Downloads") as ViewGroup).getChildAt(0) as ImageView;assertTrue(image.drawable is DownloadStatusIcon);downloads.generatedProgress(item.id,100,true);call(a,"refreshDownloadIndicator",false);assertTrue(image.drawable is DownloadStatusIcon);desc(a,"Downloads").performClick();settle(a);assertTrue(a.getSharedPreferences("browser",0).getStringSet("seen_downloads",emptySet())!!.contains(item.id.toString()));c.pause().stop().destroy()}
 @Test fun progressLeavesAddressCleanAndTabAnimationDoesNotOverlap(){val c=start();val a=c.get();val web=call(a,"getWeb") as WebView;web.webChromeClient!!.onProgressChanged(web,43);assertFalse((field(a,"addressField") as EditText).text.toString().contains("Loading"));assertEquals(View.VISIBLE,(field(a,"pageLoadBar") as View).visibility);repeat(3){call(a,"newTab");settle(a)};call(a,"switchTab",1);repeat(5){settle(a,16);val row=field(a,"tabRow") as ViewGroup;for(i in 0 until row.childCount-1){val left=row.getChildAt(i);val right=row.getChildAt(i+1);assertEquals(0f,left.translationX,.001f);assertTrue(left.right<=right.left)}};settle(a);shot(a,"tab-animation");c.pause().stop().destroy()}
 @Test fun unactivatedDomAutofocusIsReleasedButPendingUserEditingIsPreserved(){val c=start();val a=c.get();val web=call(a,"getWeb") as WebView;val shadow=Shadows.shadowOf(web);put(a,"checkingEditing",false);put(a,"editRequestedAt",android.os.SystemClock.uptimeMillis()-2000);call(a,"checkWebEditing");RecordingWebViewShadow.clearEvidence();shadow.lastEvaluatedJavascriptCallback.onReceiveValue("true");assertTrue(RecordingWebViewShadow.scripts.any{it.contains("releaseEditing()")});assertEquals(false,field(a,"webEditing"));put(a,"checkingEditing",false);put(a,"editRequestedAt",android.os.SystemClock.uptimeMillis());call(a,"checkWebEditing");RecordingWebViewShadow.clearEvidence();shadow.lastEvaluatedJavascriptCallback.onReceiveValue("true");assertFalse(RecordingWebViewShadow.scripts.any{it.contains("releaseEditing()")});c.pause().stop().destroy()}

}
